// BioCLIP 2 / TreeOfLife-200M fungal species, in the model's output order.
// Generated by ml/export_bioclip2_fungi.py.
import catalog from './fungiCatalog.json';

type CatalogRow = [genus: number, epithet: string, family: number, commonName: string, order: number, classIndex: number, phylum: number];

const rows = catalog.species as CatalogRow[];

export const GENERA: readonly string[] = catalog.genera;
export const SPECIES_COUNT = rows.length;

export function genusIndex(species: number): number {
  return rows[species][0];
}

export function scientificName(species: number): string {
  return `${GENERA[rows[species][0]]} ${rows[species][1]}`;
}

export function familyName(species: number): string {
  return catalog.families[rows[species][2]];
}

export function commonName(species: number): string | undefined {
  return rows[species][3] || undefined;
}

export function genusName(species: number): string {
  return GENERA[rows[species][0]];
}

/** Classification from kingdom to species; empty ranks are missing in the source taxonomy. */
export function classification(species: number): { rank: string; name: string }[] {
  const [genus, epithet, family, , order, class_, phylum] = rows[species];
  return [
    { rank: 'Kingdom', name: 'Fungi' },
    { rank: 'Phylum', name: catalog.phyla[phylum] },
    { rank: 'Class', name: catalog.classes[class_] },
    { rank: 'Order', name: catalog.orders[order] },
    { rank: 'Family', name: catalog.families[family] },
    { rank: 'Genus', name: GENERA[genus] },
    { rank: 'Species', name: `${GENERA[genus]} ${epithet}` },
  ];
}

export function isSpeciesIndex(value: number): boolean {
  return Number.isInteger(value) && value >= 0 && value < rows.length;
}
